def build() -> Dict[str, Dict[str, str]]:
    """Return {locale: {english_source: translation}}, including the two
    "Saropa Lints: Rate on ..." command titles derived from the base labels."""
    out: Dict[str, Dict[str, str]] = {}
    for loc, row in _ROWS.items():
        # Guard against a misaligned row silently shifting every later string.
        if len(row) != len(SOURCES):
            raise ValueError(f"manual_translations[{loc!r}]: {len(row)} != {len(SOURCES)}")
        m = dict(zip(SOURCES, row))
        m["Saropa Lints: Rate on Open VSX"] = "Saropa Lints: " + m["Rate on Open VSX"]
        m["Saropa Lints: Rate on VS Code Marketplace"] = "Saropa Lints: " + m["Rate on VS Code Marketplace"]
        out[loc] = m
    return out
